import React, { useState } from "react";
import "../Styles/UserProfile.css";

const UserProfile = () => {
  const [cvFile, setCvFile] = useState(null);

  const handleUploadCV = (e) => {
    const file = e.target.files[0];
    setCvFile(file);
    alert(`Uploaded: ${file.name}`);
  };

  return (
    <div className="profile-page">
      {/* User Info */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">👤</div>
          <div>
            <h2 className="profile-name">Aisha Ahmed</h2>
            <p className="profile-email">aisha@gmail.com</p>
            <div className="cv-section">
              <span className="cv-label">student cv</span>
              <label className="upload-btn">
                <input
                  type="file"
                  accept=".pdf,.doc,.docx"
                  onChange={handleUploadCV}
                  style={{ display: "none" }}
                />
                ⬆ Upload CV
              </label>
            </div>
          </div>
        </div>
        <button className="update-btn">Update your Info</button>
      </div>

      {/* Recent Activity */}
      <div className="activity-box">
        <h3>Recent activity</h3>
        <p>• Applied: 1 job(s)</p>
      </div>

      {/* Payment Details */}
      <div className="payment-box">
        <div>
          <h3>Payment details</h3>
          <p>Bank Name: Bank Muscat</p>
          <p>Account Number: *******1234</p>
        </div>
        <button className="update-btn">Update your Payment</button>
      </div>
    </div>
  );
};

export default UserProfile;
